corrected_code:
from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session
from sqlalchemy import select

router = APIRouter(prefix="/scheduler/history")

@router.get("/schedules/{schedule_id}/runs")
async def get_periodic_task_run_history(
    schedule_id: str,
    db: Session = Depends(get_db_session),
    current_user: User = Depends(get_current_user)
):
    schedule = db.execute(
        select(PeriodicSchedule).where(PeriodicSchedule.id == schedule_id, PeriodicSchedule.tenant_id == current_user.tenant_id)
    ).scalar_one_or_none()
    if not schedule:
        raise HTTPException(status_code=404, detail="Schedule not found")

    runs = db.execute(
        select(PeriodicTaskRun).where(PeriodicTaskRun.schedule_id == schedule_id).order_by(PeriodicTaskRun.started_at.desc()).limit(20)
    ).scalars().all()

    return {
        "schedule_id": schedule_id,
        "runs": [
            {"run_id": r.id, "started_at": r.started_at.isoformat(), "duration_ms": r.duration_ms, "status": r.status}
            for r in runs
        ]
    }
